files.content:
@use 'styles' as vz;

.content {
  display: flex;
  width: min(20rem, calc(100vw - 2rem));
  flex-direction: column;
  gap: vz.space(2);
  padding: vz.space(4);
}

.title {
  margin: 0;
  font-size: vz.font-size('sm');
  font-weight: 600;
}

.description {
  margin: 0;
  color: vz.color('muted-foreground');
  font-size: vz.font-size('xs');
  line-height: 1.5;
}

.actions {
  display: flex;
  justify-content: flex-end;
  gap: vz.space(2);
  padding-top: vz.space(1);
}
